    if (!a.workflows[key]) add('info', 'โมดูล “' + mn + '”: เพิ่ม workflow สถานะ')
    else statusWf(key, key, 'โมดูล “' + mn + '”')
  }
  for (const key of Object.keys(a.workflows).filter(k => k.startsWith('m_') && !b.workflows[k])) {
