    add(n ? 'warn' : 'info', 'ปิด workflow สถานะของโมดูล “' + ((a.modules || []).find(m => m.key === key)?.name || key) + '”' + (n ? ' — ' + n + ' รายการมีสถานะเดิมเก็บไว้ แต่ไม่แสดง' : ''))
  }
