/* ===== dashboard tiles, lists, quick create, polish ===== */
.tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 14px; margin-bottom: 20px; }
.tile { display: flex; gap: 14px; align-items: center; padding: 16px 18px; background: var(--card); border: 1px solid var(--line); border-radius: 14px; color: var(--ink); text-decoration: none; transition: border-color .15s, transform .15s; }
.tile:hover { border-color: var(--muted); transform: translateY(-1px); }
.tile-ic { width: 46px; height: 46px; border-radius: 12px; display: inline-flex; align-items: center; justify-content: center; background: var(--line2); color: var(--muted); flex-shrink: 0; }
.tile.bad .tile-ic { background: rgba(240, 95, 131, .16); color: #f05f83; }
.tile.warn .tile-ic { background: rgba(242, 176, 54, .16); color: #e0961a; }
.tile-body { display: flex; flex-direction: column; min-width: 0; }
.tile-n { font-size: 30px; font-weight: 700; line-height: 1.1; }
.tile.bad .tile-n { color: #f05f83; }
.tile-l { font-size: 16.5px; }
.tile-s { color: var(--muted); font-size: 14px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chip { display: inline-flex; align-items: center; gap: 8px; padding: 6px 14px; border: 1px solid var(--line); border-radius: 999px; background: var(--card); color: var(--ink); text-decoration: none; font-size: 16px; }
.chip:hover { border-color: var(--muted); }
.chip b { color: var(--pri); }
.list-row { display: flex; align-items: center; gap: 12px; padding: 11px 6px; border-bottom: 1px solid var(--line2); color: var(--ink); text-decoration: none; }
.list-row:last-child { border-bottom: 0; }
a.list-row:hover { background: var(--line2); border-radius: 8px; }
.lr-main { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.lr-main b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 600; }
.lr-age { white-space: nowrap; font-size: 15px; }
.avatar.sm { width: 28px; height: 28px; font-size: 13px; flex-shrink: 0; }
.create-btn { min-height: 44px; padding: 6px 16px; gap: 6px; }
.demo-banner { display: flex; align-items: center; gap: 12px; }
.demo-banner span { flex: 1; }
.demo-banner button { background: none; border: 0; color: var(--muted); text-decoration: underline; cursor: pointer; font: inherit; font-size: 14px; }
.tabs.many { flex-wrap: wrap; overflow: visible; }
.page-head { align-items: flex-end; }
.page-head .muted { margin-top: 4px; }
@media (max-width: 900px) {
  .create-label { display: none; }
  .tiles { grid-template-columns: 1fr 1fr; gap: 10px; }
  .tile { padding: 12px; gap: 10px; } .tile-ic { width: 38px; height: 38px; } .tile-n { font-size: 24px; } .tile-l { font-size: 14.5px; }
}
@media (max-width: 560px) { .tiles { grid-template-columns: 1fr; } }
@media print {
  .rail, .top, .bottombar, .demo-banner, .page-actions, .tabs, .utabs, .table-tools, .pager, .btn, .overlay { display: none !important; }
  .main2 { padding: 0 !important; }
  html[data-theme='dark'] body, html[data-theme='dark'] .content, html[data-theme='dark'] .card { background: #fff !important; color: #000 !important; }
  html[data-theme='dark'] { --ink: #000; --muted: #444; --line: #bbb; --line2: #ddd; --card: #fff; --bg: #fff; }
  .content { padding: 0; max-width: none; }
}

